import{_ as o,o as a,c as r,a6 as t}from"./chunks/framework.DNkVJs23.js";const h=JSON.parse('{"title":"Sobre Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/others/"}],["meta",{"property":"og:title","content":"Sobre Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dados de Monster Hunter e busca de conjuntos para Wilds, Rise com Sunbreak e World com Iceborne."}]]},"headers":[],"relativePath":"pt-br/others/index.md","filePath":"pt-br/others/index.md"}'),i={name:"pt-br/others/index.md"};function s(n,e,d,p,l,c){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="sobre-sapphire-star-codex" tabindex="-1">Sobre Sapphire Star Codex <a class="header-anchor" href="#sobre-sapphire-star-codex" aria-label="Permalink to &quot;Sobre Sapphire Star Codex&quot;">​</a></h1><h2 id="o-projeto" tabindex="-1">O projeto <a class="header-anchor" href="#o-projeto" aria-label="Permalink to &quot;O projeto&quot;">​</a></h2><p>Sapphire Star Codex reúne dados de Monster Hunter e busca de conjuntos de armadura. É desenvolvido e mantido de forma independente pelo criador de <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>. O app é gratuito, sem anúncios nem recursos pagos.</p><p>Android está disponível no <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> e HarmonyOS na <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. A versão para iOS está em preparação. Consulte os <a href="./../#download">downloads</a>; a disponibilidade varia conforme a região e o dispositivo.</p><h2 id="comentarios-e-colaboracao" tabindex="-1">Comentários e colaboração <a class="header-anchor" href="#comentarios-e-colaboracao" aria-label="Permalink to &quot;Comentários e colaboração&quot;">​</a></h2><p>Ao relatar um problema, informe o jogo, o registro, o idioma, os passos e uma fonte verificável. Oculte informações pessoais das capturas. Contato: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Compartilhar o app, sugerir correções e <a href="./../support/">apoiar voluntariamente</a> também ajuda.</p><h2 id="fontes-e-direitos" tabindex="-1">Fontes e direitos <a class="header-anchor" href="#fontes-e-direitos" aria-label="Permalink to &quot;Fontes e direitos&quot;">​</a></h2><p>Os dados vêm de <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> e arquivos do jogo, com conferência em fontes da comunidade. Podem existir falhas ou omissões. Nomes, imagens e dados de Monster Hunter pertencem à CAPCOM; pedidos de remoção serão respeitados. A licença MIT do código adaptado de Pocket Gallery não inclui imagens ou dados do jogo.</p>',8)])])}const f=o(i,[["render",s]]);export{h as __pageData,f as default};
